def run(amazon_url, budget_usd, country, product_page, independent_reviews, alternatives):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    def num(x):
        try:
            return float(x)
        except Exception:
            return None

    page = product_page if isinstance(product_page, dict) else {}
    title = clean(page.get('title'))
    text = clean(page.get('text'))
    url = clean(page.get('url')) or clean(amazon_url)
    status = page.get('status')

    price = None
    if isinstance(text, str) and text:
        import re
        m = re.search(r'\$(\d+(?:\.\d{1,2})?)', text)
        if m:
            price = num(m.group(1))
        if price is None:
            m = re.search(r'([0-9]+(?:\.[0-9]{1,2})?)\s*dollars', text, re.I)
            if m:
                price = num(m.group(1))

    brand = ''
    if title:
        brand = title.split()[0]

    review_signals = []
    review_count = None
    if isinstance(text, str):
        low = text.lower()
        for phrase in ['works great', 'highly recommend', 'bad quality', 'stopped working', 'poor quality', 'fake', 'scam', 'not worth']:
            if phrase in low:
                review_signals.append(phrase)
        import re
        m = re.search(r'([0-9,]+)\s+ratings?', text, re.I)
        if m:
            try:
                review_count = int(m.group(1).replace(',', ''))
            except Exception:
                pass

    indie_hits = []
    if isinstance(independent_reviews, dict):
        for r in independent_reviews.get('results', [])[:5]:
            if isinstance(r, dict):
                indie_hits.append({'title': clean(r.get('title'))[:160], 'url': clean(r.get('url')), 'snippet': clean(r.get('content'))[:260]})

    alt_hits = []
    if isinstance(alternatives, dict):
        for r in alternatives.get('results', [])[:5]:
            if isinstance(r, dict):
                alt_hits.append({'title': clean(r.get('title'))[:160], 'url': clean(r.get('url')), 'snippet': clean(r.get('content'))[:260]})

    cheap_signals_disagree = False
    if review_signals:
        bad = any(s in review_signals for s in ['bad quality', 'stopped working', 'poor quality', 'fake', 'scam', 'not worth'])
        good = any(s in review_signals for s in ['works great', 'highly recommend'])
        cheap_signals_disagree = bad and good

    return {
        'product_title': title,
        'brand': brand,
        'url': url,
        'status': status,
        'price': price,
        'currency': 'USD',
        'review_count': review_count,
        'review_signals': review_signals[:6],
        'independent_reviews': indie_hits,
        'alternatives': alt_hits,
        'cheap_signals_disagree': cheap_signals_disagree,
        'page_text_sample': text[:1200],
        'budget_usd': budget_usd
    }

def run(product_page, extracted):
    page = product_page if isinstance(product_page, dict) else {}
    extracted = extracted if isinstance(extracted, dict) else {}
    problems = []

    if page.get('status') != 200:
        problems.append('Amazon page did not return HTTP 200.')
    text = page.get('text') or ''
    if not isinstance(text, str) or not text.strip():
        problems.append('Amazon page text was empty.')
    if not extracted.get('product_title'):
        problems.append('Product title could not be extracted.')
    if extracted.get('price') is None:
        problems.append('Price could not be extracted.')
    if not extracted.get('url'):
        problems.append('Product URL is missing.')
    return {'ok': len(problems) == 0, 'problems': problems}

def run(extracted, verify):
    extracted = extracted if isinstance(extracted, dict) else {}
    verify = verify if isinstance(verify, dict) else {}
    ok = bool(verify.get('ok'))
    price = extracted.get('price')
    budget = extracted.get('budget_usd')
    if budget is None:
        budget = 100
    try:
        budget = float(budget)
    except Exception:
        budget = 100
    reasons = []
    score = 0
    escalate = False
    verdict = 'wait'

    if not ok:
        return {'score': 0, 'verdict': 'wait', 'reasons': ['Product page data was not verified.'] + (verify.get('problems') or []), 'escalate': False}

    if price is not None:
        score += 1
        if price <= budget:
            score += 1
            reasons.append('Price is within budget.')
        else:
            reasons.append('Price is above budget.')
    if extracted.get('review_count') and extracted.get('review_count') >= 1000:
        score += 1
        reasons.append('There are many ratings.')
    if extracted.get('review_signals'):
        score += 1
        reasons.append('Review text contains usable signals.')
    if extracted.get('independent_reviews'):
        score += 1
        reasons.append('Independent review hits were found.')
    if extracted.get('alternatives'):
        score += 1
        reasons.append('Cheaper alternatives were found.')

    cheap_disagree = bool(extracted.get('cheap_signals_disagree'))
    above_100 = isinstance(price, (int, float)) and price > 100
    if above_100 or cheap_disagree:
        escalate = True
        reasons.append('Escalation condition triggered.')

    if price is None:
        verdict = 'wait'
    elif price <= budget and not cheap_disagree and not above_100 and not extracted.get('alternatives'):
        verdict = 'buy'
    elif extracted.get('alternatives'):
        verdict = 'pick-an-alternative'
    else:
        verdict = 'wait'

    if cheap_disagree and extracted.get('alternatives'):
        verdict = 'pick-an-alternative'
    return {'score': score, 'verdict': verdict, 'reasons': reasons, 'escalate': escalate}

def run(amazon_url, budget_usd, extracted, verify, judge, product_reality_check, reddit_research):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    extracted = extracted if isinstance(extracted, dict) else {}
    verify = verify if isinstance(verify, dict) else {}
    judge = judge if isinstance(judge, dict) else {}
    title = clean(extracted.get('product_title')) or 'the product'
    price = extracted.get('price')
    verdict = judge.get('verdict', 'wait')
    reasons = judge.get('reasons') or []
    pr = clean(product_reality_check.get('result')) if isinstance(product_reality_check, dict) else ''
    rr = clean(reddit_research.get('result')) if isinstance(reddit_research, dict) else ''

    if not verify.get('ok'):
        speech = f'Wait on {title}. I could not verify the Amazon page cleanly, so I would not trust a purchase decision yet.'
    else:
        if verdict == 'buy':
            speech = f'Buy {title}. The price looks reasonable and the basic signals are steady.'
        elif verdict == 'pick-an-alternative':
            speech = f'Pick an alternative to {title}. The signals point to a better-value option nearby.'
        else:
            speech = f'Wait on {title}. The deal does not look clean enough for a confident buy.'

    lines = ['# Amazon Buy Check', '']
    lines.append('## Verdict')
    lines.append(f'- **Decision:** {verdict}')
    lines.append(f'- **Product:** {title}')
    lines.append(f'- **URL:** {clean(extracted.get("url")) or amazon_url}')
    lines.append(f'- **Price:** ${price:.2f}' if isinstance(price, (int, float)) else '- **Price:** unknown')
    lines.append(f'- **Budget:** ${float(budget_usd):.2f}' if budget_usd is not None else '- **Budget:** not set')
    lines.append('')
    lines.append('## Reasons')
    for r in reasons[:8]:
        lines.append(f'- {clean(r)}')
    if verify.get('problems'):
        lines.append('')
        lines.append('## Verification problems')
        for p in verify.get('problems', [])[:8]:
            lines.append(f'- {clean(p)}')
    if pr:
        lines.append('')
        lines.append('## Product Reality Check')
        lines.append(pr)
    if rr:
        lines.append('')
        lines.append('## Reddit Research')
        lines.append(rr)
    if extracted.get('independent_reviews'):
        lines.append('')
        lines.append('## Independent review hits')
        for hit in extracted.get('independent_reviews', [])[:5]:
            if isinstance(hit, dict):
                lines.append(f'- {clean(hit.get("title"))}: {clean(hit.get("snippet"))} {clean(hit.get("url"))}')
    if extracted.get('alternatives'):
        lines.append('')
        lines.append('## Cheaper alternatives')
        for hit in extracted.get('alternatives', [])[:5]:
            if isinstance(hit, dict):
                lines.append(f'- {clean(hit.get("title"))}: {clean(hit.get("snippet"))} {clean(hit.get("url"))}')

    report = '\n'.join(lines)
    return {'speech': speech[:900], 'report': report}
